<template>
	<view>
		<u-sticky>
			<view class="head_box">
				<view class="box_1 d-flex a-center j-center" @click="show=true">
					<image src="../static/icon14.png" mode=""></image>
					<span class="ml-16">新增规格</span>
				</view>
			</view>

		</u-sticky>

		<view class="box_2 mb-30" v-for="(item,index) in list" :key="item.id">
			<view class="d-flex a-center j-sb">
				<view class="box_2_title">
					{{item.name}}
				</view>
				<view class="d-flex a-center">
					<u-icon name='edit-pen' size="24" @click="show=true,specid=item.id"></u-icon>
					<image class="mr-10 del-img ml-30" src="../static/cicon12.png" mode="aspectFill"
						@click="delitem(item.id)">
				</view>
			</view>

			<view class="box_2_card d-flex a-center j-sb">
				<input maxlength="10" type="text" placeholder="请输入具体规格" v-model="item.item_name" />
				<view class="box_2_card_btn" @click="execSpecItemApi(item.id,item.item_name)">
					增加
				</view>
			</view>
			<view class=" mt-20  d-flex a-center flex-wrap">
				<view class="box_2_bom mr-24 mb-14 d-flex a-center" :key="item1" v-for="(item1,index1) in item.item">
					<image class="mr-10" src="../static/cicon12.png" mode="" @click="delSpecItemApi(item1.id)"></image>
					<span class="color-6 f-size-28">{{item1.name}}</span>
				</view>
			</view>
		</view>
		<empty v-if="list.length<=0"></empty>
		<u-popup :show="show" @close="show=false" :round="10" :closeable='true'>
			<view class="pop_box">
				<view class="txt-center f-size-30 f-600">
					规格
				</view>
				<view class="ipt_box">
					<input maxlength="10" type="text" v-model="specName" placeholder="请输入规格名称" />
				</view>
				<view class="ipt_btn" @click="execSpecApi">
					保存
				</view>
			</view>
		</u-popup>
	</view>
</template>

<script>
	export default {
		data() {
			return {
				show: false,
				specName: '',
				specid: "",
				list: [],
				item_name: "",
				page: 1
			};
		},
		onLoad() {
			this.specListApi()
		},
		onReachBottom() {
			this.page++
			this.specListApi(1)
		},
		methods: {
			async delSpecItemApi(id) {
				let res = await this.delSpecItem({
					id
				})
				if (res.code == 1) {
					this.list.forEach(item => {
						item.item.forEach((item1, index1) => {
							if (item1.id == id) {
								item.item.splice(index1, 1)
							}
						})
					})
					this.$forceUpdate()
				}
			},
			// 删除参数
			async delitem(id) {
				let res = await this.delSpec({
					id
				})
				if (res.code == 1) {
					this.list.forEach((item, index) => {
						if (item.id == id) {
							this.list.splice(index, 1)
						}
					})

					this.$forceUpdate()
				}
			},
			// 添加参数项目
			async execSpecItemApi(spec_id, name) {
				let res = await this.execSpecItem({
					name: name,
					spec_id,
				})
				if (res.code == 1) {
					this.list.forEach(item => {
						item.item_name = ''
					})
					this.specListApi()
				}
			},
			// 新增规格
			async execSpecApi() {
				let res = await this.execSpec({
					name: this.specName,
					id: this.specid
				})
				if (res.code == 1) {
					this.specName = ''
					this.specid = ''
					this.show = false
					this.specListApi()
				}
			},
			// 规格列表
			async specListApi(e) {
				if (e !== 1) {
					this.page = 1
				}
				let res = await this.specList({
					page: this.page
				})
				if (res.code == 1) {
					res.data.rows.forEach(item => {
						item.item_name = ''
					})
					if (e == 1) {
						this.list = [...this.list, ...res.data.rows]
					} else {
						this.list = res.data.rows
					}
				}
			}
		}
	}
</script>

<style lang="scss">
	page {
		padding: 0 30rpx 30rpx;
		box-sizing: border-box;
	}

	.head_box {
		padding: 20rpx 0;
		box-sizing: border-box;
		background-color: #fff;
	}

	.box_1 {
		// width: 690rpx;
		height: 74rpx;
		background: #F8F9FC;
		border-radius: 4rpx 4rpx 4rpx 4rpx;
		font-weight: 400;
		font-size: 32rpx;
		color: #3D3D3D;
		text-align: center;
		padding: 16rpx 0;
		box-sizing: border-box;

		image {
			width: 36rpx;
			height: 36rpx;
		}
	}

	.box_2 {
		.box_2_title {
			font-weight: bold;
			font-size: 34rpx;
			color: #3D3D3D;
			margin: 22rpx 0;

		}

		.box_2_card {
			width: 690rpx;
			height: 90rpx;
			background: #F8F9FC;
			border-radius: 16rpx 16rpx 16rpx 16rpx;
			position: relative;
			padding-left: 34rpx;

			.box_2_card_btn {

				width: 176rpx;
				height: 90rpx;
				background: #036045;
				border-radius: 16rpx 16rpx 16rpx 16rpx;
				font-weight: 400;
				font-size: 28rpx;
				color: #FFFFFF;
				line-height: 90rpx;
				text-align: center;
			}
		}

		.box_2_bom {
			image {
				width: 34rpx;
				height: 34rpx;
			}
		}
	}

	.del-img {
		width: 34rpx;
		height: 34rpx;
	}

	.ipt_box {
		width: 690rpx;
		height: 90rpx;
		background: #F8F9FC;
		border-radius: 16rpx 16rpx 16rpx 16rpx;
		padding: 22rpx 30rpx;
		box-sizing: border-box;
		margin: 60rpx 0 100rpx;
	}

	.pop_box {
		width: 750rpx;
		height: 544rpx;
		background: #FFFFFF;
		border-radius: 40rpx 40rpx 0rpx 0rpx;
		padding: 32rpx;
		box-sizing: border-box;

		.ipt_btn {
			width: 690rpx;
			height: 102rpx;
			background: #036045;
			border-radius: 1246rpx 1246rpx 1246rpx 1246rpx;
			text-align: center;
			line-height: 102rpx;
			font-size: 28rpx;
			color: #FFFFFF;
		}
	}
</style>